// Independent check of team_count: the same first leads, with primes generated by primesieve (Kim Walisch) instead of
// our own sieve. For each modulus q given: the first prime p <= X with G_q(p) > 0 (0 if none), G_q(X) and max G_q.
// G_q = rho #{p in R} - #{p not dividing q}; the residue set R and rho are recomputed here from scratch.
// Chunks of CH integers are processed in parallel (sum of increments and maximal prefix); the first chunk where the
// running maximum becomes positive is re-scanned serially to locate the prime.
// usage: check_primesieve X q1 [q2 ...]
// cc -O2 -fopenmp check_primesieve.c -I$ENV/include -L$ENV/lib -Wl,-rpath,$ENV/lib -lprimesieve -o check_primesieve
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <primesieve.h>

#define NQ 16
static int nq, qs[NQ], w[NQ][256];
static const uint64_t CH = 2000000000ULL;

static void scan(uint64_t lo, uint64_t hi, int64_t *pref, int64_t *mx, uint64_t *first) {
    // primes in [lo, hi]; pref holds the running G on entry and on exit
    primesieve_iterator it;
    primesieve_init(&it);
    primesieve_jump_to(&it, lo, hi);
    uint64_t p;
    while ((p = primesieve_next_prime(&it)) <= hi) {
        for (int k = 0; k < nq; k++) {
            int c = w[k][p % qs[k]];
            if (!c) continue;
            pref[k] += c;
            if (mx && pref[k] > mx[k]) mx[k] = pref[k];
            if (first && !first[k] && pref[k] > 0) first[k] = p;
        }
    }
    primesieve_free_iterator(&it);
}

int main(int argc, char **argv) {
    uint64_t X = (uint64_t)atof(argv[1]);
    for (int a = 2; a < argc; a++) {
        int q = atoi(argv[a]), k = nq++; qs[k] = q;
        int unit[256] = {0}, sq[256] = {0}, nu = 0, nr = 0;
        for (int b = 1; b < q; b++) { int g = q, h = b; while (h) { int t = g % h; g = h; h = t; } if (g == 1) { unit[b] = 1; nu++; } }
        for (int b = 1; b < q; b++) if (unit[b]) sq[(b * b) % q] = 1;
        for (int b = 1; b < q; b++) if (unit[b] && sq[b]) nr++;
        for (int b = 0; b < q; b++) w[k][b] = unit[b] ? (sq[b] ? nu / nr - 1 : -1) : 0;
    }
    uint64_t nc = X / CH + 1;
    int64_t *sum = calloc(nc * nq, sizeof(int64_t)), *mx = malloc(nc * nq * sizeof(int64_t));
    #pragma omp parallel for schedule(dynamic, 1)
    for (uint64_t c = 0; c < nc; c++) {
        uint64_t lo = c * CH, hi = (c + 1) * CH - 1; if (hi > X) hi = X;
        int64_t pref[NQ] = {0}, m[NQ];
        for (int k = 0; k < nq; k++) m[k] = INT64_MIN;
        scan(lo, hi, pref, m, NULL);
        for (int k = 0; k < nq; k++) { sum[c * nq + k] = pref[k]; mx[c * nq + k] = m[k]; }
        static uint64_t done = 0; uint64_t d;
        #pragma omp atomic capture
        d = ++done;
        if (d % 1000 == 0) { fprintf(stderr, "%llu/%llu chunks\n", (unsigned long long)d, (unsigned long long)nc); }
    }
    printf("# X=%llu (primesieve %s)\n", (unsigned long long)X, primesieve_version());
    for (int k = 0; k < nq; k++) {
        int64_t off = 0, gmax = INT64_MIN; uint64_t first = 0;
        for (uint64_t c = 0; c < nc; c++) {
            int64_t m = mx[c * nq + k];
            if (m != INT64_MIN && off + m > gmax) gmax = off + m;
            if (!first && m != INT64_MIN && off + m > 0) {
                uint64_t lo = c * CH, hi = (c + 1) * CH - 1; if (hi > X) hi = X;
                int sq = qs[0], sw[256]; for (int b = 0; b < 256; b++) sw[b] = w[0][b];
                int snq = nq; qs[0] = qs[k]; for (int b = 0; b < 256; b++) w[0][b] = w[k][b]; nq = 1;
                int64_t pr[NQ] = {off}; uint64_t f[NQ] = {0};
                scan(lo, hi, pr, NULL, f);
                nq = snq; qs[0] = sq; for (int b = 0; b < 256; b++) w[0][b] = sw[b];
                first = f[0];
            }
            off += sum[c * nq + k];
        }
        printf("team %d first %llu G(X) %lld maxG %lld\n", qs[k], (unsigned long long)first, (long long)off, (long long)gmax);
    }
    return 0;
}
